import { fileURLToPath } from "node:url";
import type { QueryRows } from "./checks.js";

/** The SQL migrations shipped with this package (generated by drizzle-kit, plus custom ones). */
export const migrationsFolder = fileURLToPath(new URL("../migrations", import.meta.url));

/**
 * When the last migration before the squash (T-1408) was stamped: 0071_tenant_storage, at
 * 8ccdef5. 0000_baseline and 0001_rls carry this stamp or one earlier, so a database migrated
 * through 0071, which recorded it, skips them (Drizzle applies only what is newer than the last
 * migration it recorded) and a new database runs them.
 */
export const SQUASHED_THROUGH = 1792093503792;

/**
 * A database that recorded migrations, but none as late as {@link SQUASHED_THROUGH}, stopped
 * part way through the migrations the baseline replaced: the baseline would run over its tables.
 */
export async function checkMigrationLedger(query: QueryRows): Promise<string[]> {
  const [ledger] = await query(
    `select to_regclass('drizzle.__drizzle_migrations') is not null as made`,
  );
  if (ledger?.made !== true) return [];
  const [last] = await query(
    `select max(created_at)::text as at from drizzle.__drizzle_migrations`,
  );
  if (last?.at == null || Number(last.at) >= SQUASHED_THROUGH) return [];
  return [
    `the database's migrations stop before 0071_tenant_storage, the last one before they were ` +
      `squashed: run OpenHoard at commit 8ccdef5 against it once to finish them, then this version.`,
  ];
}
